    return `${JSON.stringify(spec, null, 2)}\n\n${report(notes)}\nPaste this array as "openingHoursSpecification" inside your LocalBusiness markup. Format: Google local business documentation (closed all day = opens and closes 00:00, open 24 hours = 00:00 to 23:59, seasonal hours use validFrom and validThrough), read ${GOOGLE_DOCS_DATE}.`;
