    setv(o, 'datePublished', isoDate(F.g('datePublished'), tz, N, 'datePublished')); setv(o, 'dateModified', isoDate(F.g('dateModified'), tz, N, 'dateModified'));
    const au = F.all('author').map((v) => { const [n, u] = pipe(v, 2); const p = { '@type': 'Person', name: n }; setv(p, 'url', u); if (u && !isAbs(u)) N.push(['WARN', `Author URL "${u}" should be absolute.`]); return p; }); setv(o, 'author', one(au));
    if (F.g('publisher')) { const [n, l] = pipe(F.g('publisher'), 2); o.publisher = { '@type': 'Organization', name: n }; if (l) o.publisher.logo = { '@type': 'ImageObject', url: l }; }
