    if (xl && lang && xl.toLowerCase() !== lang.toLowerCase()) I.push(['WARN', `xml:lang "${xl}" differs from lang "${lang}".`]);
    const mc = (h.match(/<meta\b[^>]*http-equiv\s*=\s*["']?content-language["']?[^>]*>/i) || [])[0]; if (mc) sig.push(['meta content-language', chk(ATTR(mc, 'content') || '', 'meta content-language')]);
    const hc = (hd || '').match(/^\s*content-language\s*:\s*(.+)$/im); if (hc) sig.push(['Content-Language header', chk(hc[1].split(',')[0].trim(), 'Content-Language header')]);
    const can = ((h.match(/<link\b[^>]*rel\s*=\s*["']?canonical["']?[^>]*>/i) || [])[0] || '').length ? ATTR(h.match(/<link\b[^>]*rel\s*=\s*["']?canonical["']?[^>]*>/i)[0], 'href') : undefined;
    const alts = parseAnn(h).pages[0].entries; const self = can ? alts.find((a) => a.href === can) : undefined;
    if (alts.length && !can) I.push(['INFO', 'hreflang present but no canonical, so the self-reference cannot be matched to this page.']);
    if (self) sig.push(['self hreflang', chk(self.code, 'self hreflang')]); else if (alts.length && can) I.push(['WARN', `No hreflang entry points at the canonical URL ${can} (every version should list itself).`]);
    const prim = (x) => x.split('-')[0], reg = (x) => (x.split('-').find((y, i) => i > 0 && /^([a-z]{2}|\d{3})$/.test(y)) || '');
    const base = new Set(sig.map(([, v]) => prim(v)).filter((v) => v !== 'x'));
