    const li = rows.map(([c, u, lab]) => { const r = hlCheck(c); if (r.E.length) throw new Error(`${c}: ${r.E[0]}`); if (!isAbs(u)) N.push(['WARN', `${c}: absolute URLs are best for alternates.`]); const label = lab || (safeNameIn(r.canon) || r.canon); const isCur = c.toLowerCase() === (cur || '').toLowerCase(); return isCur ? `    <li><a href="${esc(u)}" hreflang="${esc(c)}" lang="${esc(c)}" aria-current="page">${esc(label)}</a></li>` : `    <li><a href="${esc(u)}" hreflang="${esc(c)}" lang="${esc(c)}">${esc(label)}</a></li>`; });
    if (!rows.some(([c]) => c.toLowerCase() === (cur || '').toLowerCase())) N.push(['WARN', 'The current page code is not in the list.']);
    return `<nav aria-label="${esc(name || 'Language')}">\n  <ul>\n${li.join('\n')}\n  </ul>\n</nav>${tags ? '\n\n<!-- in <head> -->\n' + rows.map(([c, u]) => `<link rel="alternate" hreflang="${esc(c)}" href="${esc(u)}">`).join('\n') : ''}\n\n${report(N)}\nWhy this shape: real links are crawlable and work without JavaScript; the lang attribute makes screen readers pronounce each name in its own language; aria-current marks where you are; each label is written in its own language (native names) so people can find theirs. Do not use flags to stand for languages. A select element that navigates on change is harder for keyboard and screen reader users.`;
