// ---------- slugs ----------
const CYR = { а: 'a', б: 'b', в: 'v', г: 'g', д: 'd', е: 'e', ё: 'yo', ж: 'zh', з: 'z', и: 'i', й: 'y', к: 'k', л: 'l', м: 'm', н: 'n', о: 'o', п: 'p', р: 'r', с: 's', т: 't', у: 'u', ф: 'f', х: 'kh', ц: 'ts', ч: 'ch', ш: 'sh', щ: 'shch', ъ: '', ы: 'y', ь: '', э: 'e', ю: 'yu', я: 'ya', і: 'i', ї: 'yi', є: 'ye', ґ: 'g', ў: 'u', ђ: 'dj', ј: 'j', љ: 'lj', њ: 'nj', ћ: 'c', џ: 'dz' };
const GRK = { α: 'a', β: 'v', γ: 'g', δ: 'd', ε: 'e', ζ: 'z', η: 'i', θ: 'th', ι: 'i', κ: 'k', λ: 'l', μ: 'm', ν: 'n', ξ: 'x', ο: 'o', π: 'p', ρ: 'r', σ: 's', ς: 's', τ: 't', υ: 'y', φ: 'f', χ: 'ch', ψ: 'ps', ω: 'o' };
const LAT = { ß: 'ss', æ: 'ae', œ: 'oe', ø: 'o', đ: 'd', ð: 'd', þ: 'th', ł: 'l', ı: 'i', ħ: 'h', ŋ: 'ng' };
function translit(s, de) {
  let o = ''; for (const ch of s.toLowerCase().normalize('NFC').replace(/ο[υύ]/g, 'ou')) {
    if (de && 'äöü'.includes(ch)) { o += { ä: 'ae', ö: 'oe', ü: 'ue' }[ch]; continue; }
    if (CYR[ch] !== undefined) { o += CYR[ch]; continue; } if (LAT[ch] !== undefined) { o += LAT[ch]; continue; }
    const d = ch.normalize('NFD'); if (GRK[d[0]] !== undefined) { o += GRK[d[0]]; continue; }
    o += d.replace(/[\u0300-\u036f]/g, '');
  }
  return o;
}
add({
  id: 'translated-slug-generator', cat: 'SEO – Generators', title: 'Localized URL Slug Generator (Transliteration)',
  desc: 'Make URL slugs from titles in Cyrillic, Greek and accented Latin scripts: an ASCII slug or a native-script slug with percent-encoding.',
  labels: ['Titles, one per line'], sample: 'Привет, мир! Как дела?\nΓειά σου κόσμε\nÜber uns: Straße & Café\nZażółć gęślą jaźń\n東京の天気',
  opts: [{ id: 'mode', label: 'Slug type', type: 'select', choices: ['ascii', 'native'], def: 'ascii' }, { id: 'de', label: 'German style (ä = ae)', type: 'checkbox', def: false }, { id: 'sep', label: 'Separator', type: 'select', choices: ['-', '_'], def: '-' }, { id: 'max', label: 'Max length', type: 'number', def: 80 }],
  run: ([t], { mode, de, sep, max }) => lines(need(t, 'titles')).map((l) => {
    let s = mode === 'native' ? l.toLowerCase().normalize('NFC').replace(/[^\p{L}\p{N}\p{M}]+/gu, sep) : translit(l, de).replace(/[^a-z0-9]+/g, sep);
    s = s.replace(new RegExp(`^\\${sep}+|\\${sep}+$`, 'g'), ''); if (max > 0 && s.length > max) s = s.slice(0, max).replace(new RegExp(`\\${sep}[^${sep}]*$`), '') || s.slice(0, max);
    if (mode === 'ascii' && !s) return `${l}  =>  [REVIEW] nothing left after transliteration (script not covered); use native mode.`;
    return mode === 'native' ? `${l}  =>  ${s}\n    encoded: ${s.split(sep).map(encodeURIComponent).join(sep)}` : `${l}  =>  ${s}`;
  }).join('\n') + '\n\nASCII mode covers Cyrillic (Russian, Ukrainian, Serbian), Greek and Latin letters with accents. Arabic, Hebrew, Indic, Thai and CJK have no simple letter-for-letter rule: use native mode, where browsers show the readable form and links carry percent-encoding. Transliteration is a simplified common scheme, not ISO 9 or ELOT 743.',
});

// ---------- RTL ----------
const RTL_LANGS = new Set('ar he fa ur ps sd ug yi dv ckb'.split(' '));
add({
  id: 'rtl-layout-checker', cat: 'SEO – Technical', title: 'RTL Layout and Bidi Checker for Arabic and Hebrew HTML',
  desc: 'Check dir and lang on right-to-left HTML, and flag Latin text, numbers, URLs and physical CSS that may need bdi, dir or logical properties.',
  labels: ['HTML of a right-to-left page'], sample: `<html lang="ar">
<body>
<h1>مرحبا بكم في موقعنا</h1>
<p style="text-align:left">اتصل بنا على الرقم +32 2 123 45 67 أو زر example.com/ar لمعرفة المزيد عن منتج iPhone 15 الجديد.</p>
<p dir="rtl">שלום עולם, ראו https://example.com/he</p>
<div dir="sideways">x</div>
</body></html>`,
  run: ([h]) => {
    need(h, 'HTML'); const I = [], tree = parseHtml(h), els = allEls(tree), html = els.find((e) => e.tag === 'html');
    const isRtlChar = (s) => /[֐-ࣿיִ-﷿ﹰ-﻿]/.test(s);
    const lang0 = html?.attrs.lang?.split(/[-_]/)[0].toLowerCase(), rtlPage = lang0 && RTL_LANGS.has(lang0);
    if (!html) I.push(['WARN', 'No <html> element found.']);
    if (rtlPage && (html.attrs.dir || '').toLowerCase() !== 'rtl') I.push(['ERROR', `<html lang="${html.attrs.lang}"> is a right-to-left language but <html> has no dir="rtl". Set dir="rtl" so the whole page layout and punctuation follow right-to-left order.`]);
    if (html && !html.attrs.lang) I.push(['WARN', '<html> has no lang attribute.']);
    if (!rtlPage && (html?.attrs.dir || '').toLowerCase() === 'rtl' && lang0) I.push(['WARN', `dir="rtl" on <html> but lang="${html.attrs.lang}" is usually written left to right.`]);
    for (const e of els) { if (e.attrs.dir !== undefined && !/^(ltr|rtl|auto)$/i.test(e.attrs.dir)) I.push(['ERROR', `<${e.tag} dir="${e.attrs.dir}">: dir must be ltr, rtl or auto.`]); if (/(^|;)\s*(text-align|float)\s*:\s*(left|right)|margin-(left|right)|padding-(left|right)|(^|;)\s*(left|right)\s*:/i.test(e.attrs.style || '') && (rtlPage || (e.attrs.dir || '').toLowerCase() === 'rtl' || isRtlChar(textOf(e)))) I.push(['REVIEW', `<${e.tag}> uses a physical direction in inline style (${(e.attrs.style.match(/(text-align|float|margin-left|margin-right|padding-left|padding-right|left|right)\s*:\s*[^;]+/i) || [''])[0]}). In RTL pages prefer logical properties (text-align:start, margin-inline-start).`]); }
    // embedded LTR runs inside RTL text
    const visit = (n, ctxRtl, skip) => {
      if (n.text !== undefined) { if (skip || !ctxRtl) return; const t = n.text; if (!isRtlChar(t)) return; for (const m of t.matchAll(/(https?:\/\/\S+|[\w.-]+@[\w.-]+\.\w+|[\w-]+(?:\.[\w-]+)+\/\S*|\+?\d[\d\s().-]{5,}\d|[A-Za-z][A-Za-z0-9]*(?:[ -][A-Za-z0-9]+)*)/g)) { const s = m[0]; I.push(['REVIEW', `Left-to-right text "${s.length > 40 ? s.slice(0, 39) + '…' : s}" sits inside right-to-left text. Punctuation next to it can jump to the wrong side; wrap it in <bdi> or <span dir="ltr">.`]); } return; }
      const d = (n.attrs?.dir || '').toLowerCase(); const rtl = d === 'rtl' ? true : d === 'ltr' ? false : ctxRtl;
      const guard = skip || /^(bdi|bdo|script|style|code|pre)$/.test(n.tag) || d === 'ltr' || (d === 'auto');
      for (const k of n.kids || []) visit(k, rtl, guard);
    };
    visit(tree, !!rtlPage, false);
    if (/[‪-‮⁦-⁩]/.test(h)) I.push(['INFO', 'The source contains invisible Unicode bidi control characters. They can hide text-order tricks; prefer dir and bdi.']);
    if (!els.some((e) => e.tag === 'bdi' || /dir/.test(Object.keys(e.attrs).join()))) I.push(['INFO', 'No dir or bdi found anywhere. Fine for pure RTL text; add them for mixed content.']);
    return `${report(I)}\n\nHeuristic reading of the HTML source: it cannot see CSS files, rendered layout or text added by scripts. Findings marked REVIEW are likely but not certain problems. Based on the HTML rules for dir, bdi and bdo.`;
  },
});

// ---------- multilingual title width ----------
function glyphW(ch) {
  const c = ch.codePointAt(0);
  if ((c >= 0x0300 && c <= 0x036f) || c === 0x0e31 || (c >= 0x0e34 && c <= 0x0e3a) || (c >= 0x0e47 && c <= 0x0e4e) || (c >= 0x0900 && c <= 0x0903) || (c >= 0x093a && c <= 0x094f && ![0x093d].includes(c)) || (c >= 0x064b && c <= 0x065f) || (c >= 0x0591 && c <= 0x05c7)) return 0;
  if ((c >= 0x2e80 && c <= 0x9fff) || (c >= 0xac00 && c <= 0xd7af) || (c >= 0x3040 && c <= 0x30ff) || (c >= 0xff00 && c <= 0xffef) || (c >= 0x3000 && c <= 0x303f) || c >= 0x20000) return 1;
  if (c >= 0x1f300) return 1.1;
  if (c >= 0x0e00 && c <= 0x0e7f) return 0.56; if (c >= 0x0900 && c <= 0x097f) return 0.6; if (c >= 0x0600 && c <= 0x06ff) return 0.5; if (c >= 0x0590 && c <= 0x05ff) return 0.52; if (c >= 0x0400 && c <= 0x04ff) return 0.6; if (c >= 0x0370 && c <= 0x03ff) return 0.6;
  if (/[ijl.,:;'|!I’ ft]/.test(ch)) return 0.27; if (/[r()\-[\]{}"]/.test(ch)) return 0.34; if (ch === 'm' || ch === 'M') return 0.83; if (ch === 'W') return 0.94; if (ch === 'w') return 0.72; if (/[A-Z]/.test(ch)) return 0.69; if (/[a-z]/.test(ch)) return 0.54; if (/[0-9]/.test(ch)) return 0.556; return 0.58;
}
add({
  id: 'multilingual-title-width-checker', cat: 'SEO – On-page', title: 'Multilingual Title Width Checker (CJK, Thai, Arabic, Cyrillic)',
  desc: 'Estimate title pixel width per script and see where each title would be cut off. CJK glyphs are about twice as wide as Latin ones.',
  labels: ['Titles, one per line'], sample: 'Free SEO tools that run in your browser\n無料のSEOツール: ブラウザで動くチェッカー集\nأدوات سيو مجانية تعمل داخل المتصفح\nБесплатные SEO-инструменты в вашем браузере\nเครื่องมือ SEO ฟรีที่ทำงานในเบราว์เซอร์ของคุณ\n無料のSEOツール: ブラウザだけで動くチェッカー集、メタタグ、構造化データ、hreflangの確認',
  opts: [{ id: 'limit', label: 'Width limit (px)', type: 'number', def: 600 }, { id: 'size', label: 'Font size (px)', type: 'number', def: 20 }],
  run: ([t], { limit, size }) => lines(need(t, 'titles')).map((l) => {
    let w = 0, cut = -1, i = 0; const chars = [...l]; for (const ch of chars) { w += glyphW(ch) * size; if (cut < 0 && w > limit - glyphW('…') * size) cut = i; i++; }
    const over = w > limit, idx = cut < 0 ? chars.length : cut, shown = over ? chars.slice(0, Math.max(1, idx)).join('') + '…' : l;
    return `${over ? 'REVIEW' : 'OK    '} ~${Math.round(w)}px of ${limit}px, ${chars.length} characters\n  ${l}${over ? `\n  would show: ${shown}` : ''}`;
  }).join('\n') + `\n\nWidths are rough per-script estimates (Latin from an Arial-like table; CJK, kana, Hangul and full-width forms 1 em; Thai, Devanagari, Arabic, Hebrew, Cyrillic and Greek 0.5 to 0.6 em; combining marks 0). Google uses its own fonts and says it truncates by pixel width, not characters, and publishes no exact limit. The 600px at 20px figure is a common community rule of thumb. Treat results as a guide.`,
});

add({
  id: 'content-language-header-builder', cat: 'SEO – Generators', title: 'Content-Language Header Builder',
  desc: 'Build a Content-Language header, the matching meta http-equiv tag and html lang, plus Apache and nginx config lines.',
  labels: ['Language tags, one per line (first is the main language)'], sample: 'en-GB',
  run: ([t]) => {
    const tags = lines(need(t, 'language tags')).map((l) => { const r = hlCheck(l); if (r.E.length) throw new Error(`${l}: ${r.E[0]}`); return r.canon; }); const v = tags.join(', ');
    return `HTTP header:\nContent-Language: ${v}\n\nHTML meta equivalent (in <head>):\n<meta http-equiv="content-language" content="${v}">\n\nHTML lang (for browsers and assistive technology, set it too):\n<html lang="${tags[0]}">\n\nApache (mod_headers):\nHeader set Content-Language "${v}"\n\nnginx:\nadd_header Content-Language "${v}" always;\n\nNotes:\n- Content-Language names the intended audience language(s) of the content. It is not a way to request a language (that is Accept-Language).\n- Google says it does not use hreflang or the lang attribute to detect page language, and does not list Content-Language as a signal; use hreflang for alternates.\n- Bing: community and older sources say Bing reads the Content-Language meta tag or header and the html lang attribute, and that it does not use hreflang. I could not confirm this on Bing's current official documentation, so check Bing Webmaster Guidelines before relying on it.\n- Several tags in one header mean the content is meant for readers of all of them; for a single-language page use one tag.`;
  },
});

// ---------- Search Console export ----------
add({
  id: 'search-console-locale-traffic-checker', cat: 'SEO – Technical', title: 'Search Console Wrong-Locale Traffic Checker (CSV)',
  desc: 'Paste a Search Console export of clicks by page and country and see how much traffic each language version gets from outside its market.',
  inputs: 2, labels: ['CSV: page, country, clicks (optional impressions). Country as name or ISO code.', 'Market of each version: "URL prefix | country codes" per line'],
  sample: 'page,country,clicks,impressions\nhttps://example.com/fr/,France,820,15000\nhttps://example.com/fr/,Belgium,130,2500\nhttps://example.com/fr/,Canada,60,900\nhttps://example.com/en/,France,410,9000\nhttps://example.com/en/,United Kingdom,700,12000\nhttps://example.com/en/,United States,300,5200',
  sample2: 'https://example.com/fr/ | FR, BE, CA, CH\nhttps://example.com/en/ | GB, US, IE, AU',
  run: ([c, m]) => {
    const rows = parseCsv(need(c, 'a CSV')).filter((r) => r.some((x) => x.trim())), h = rows[0].map((x) => x.trim().toLowerCase());
    const ip = h.findIndex((x) => /page|url/.test(x)), ic = h.findIndex((x) => /countr/.test(x)), ik = h.findIndex((x) => /click/.test(x)); if (ip < 0 || ic < 0 || ik < 0) throw new Error('Header row must contain page, country and clicks columns.');
    const nameToCode = new Map([...REGIONS].map((r) => [safeName(RN, r).toLowerCase(), r])); [['united states of america', 'US'], ['turkey', 'TR'], ['türkiye', 'TR'], ['czech republic', 'CZ'], ['south korea', 'KR'], ['russia', 'RU'], ['vietnam', 'VN'], ['uk', 'GB']].forEach(([k, v]) => nameToCode.set(k, v));
    const iso3 = {}; const toCode = (x) => { x = x.trim(); if (/^[A-Za-z]{2}$/.test(x) && REGIONS.has(x.toUpperCase())) return x.toUpperCase(); return nameToCode.get(x.toLowerCase()) || null; };
    const markets = lines(need(m, 'markets')).map((l) => { const [p, cs] = pipe(l, 2); return { p, cs: new Set(cs.split(/[\s,;]+/).filter(Boolean).map((x) => x.toUpperCase())) }; });
    const agg = new Map(), unk2 = new Set(); markets.forEach((x) => agg.set(x.p, { tot: 0, inn: 0, out: new Map() }));
    for (const r of rows.slice(1)) { const page = (r[ip] || '').trim(), cc = toCode(r[ic] || ''), k = +(r[ik] || '').replace(/[,\s]/g, ''); if (!page || !Number.isFinite(k)) continue; if (!cc) { unk2.add(r[ic]); continue; } const mk = markets.filter((x) => page.startsWith(x.p)).sort((a, b) => b.p.length - a.p.length)[0]; if (!mk) continue; const a = agg.get(mk.p); a.tot += k; if (mk.cs.has(cc)) a.inn += k; else a.out.set(cc, (a.out.get(cc) || 0) + k); }
    const out = [];
    for (const x of markets) { const a = agg.get(x.p); if (!a.tot) { out.push(`${x.p}: no clicks found`); continue; } const pc = Math.round((a.inn / a.tot) * 100); const top = [...a.out].sort((p, q) => q[1] - p[1]).slice(0, 5).map(([k, v]) => `${k} ${v} (${safeName(RN, k)})`); out.push(`${x.p}\n  ${a.tot} clicks, ${pc}% from its markets (${[...x.cs].join(', ')}), ${100 - pc}% from elsewhere\n  Top outside markets: ${top.join(', ') || 'none'}\n  ${pc < 60 ? '[REVIEW] A large share comes from outside the intended markets. Check hreflang, the content language of competing versions, and whether another version should rank there.' : '[OK] Most clicks come from the intended markets.'}`); }
    return `${out.join('\n\n')}${unk2.size ? `\n\n[INFO] Countries not recognised (ignored): ${[...unk2].join(', ')}` : ''}\n\nThis reads a file you export from Search Console (Performance, filter by page, group by country); nothing is fetched. Traffic from outside the intended market is not always wrong (travellers, expatriates, a language shared across countries). The threshold of 60% is a judgement call. A page-by-country export is limited by Search Console's row limits.`;
  },
});

export default T;
